from pathlib import Path
import re

app=Path('CaddieOS/App.js')
s=app.read_text()
if 'BUILD73_COURSE_VIEW' not in s:
    s=s.replace('const BUILD72_EMPTY_ROUTINE=true;', 'const BUILD72_EMPTY_ROUTINE=true;\nconst BUILD73_COURSE_VIEW=true;', 1)

s=s.replace("const PARS=[4,5,4,3,4,4,4,5,4,4,3,4,5,4,5,3,3,4];", "const PARS=[4,5,4,3,4,4,4,5,4,4,3,4,5,4,5,3,3,4];\nconst STROKE_INDEX=[7,3,9,17,1,11,5,15,13,8,18,10,2,12,4,16,14,6];", 1)

old="const[bag,setBag]=useState(DEFAULT_BAG),[course,setCourse]=useState(''),[tee,setTee]=useState('White'),[hole,setHole]=useState('1'),[targets,setTargets]=useState(blankTargets()),[gps,setGps]=useState(null),[gpsLive,setGpsLive]=useState(false);"
new="const[bag,setBag]=useState(DEFAULT_BAG),[course,setCourse]=useState(''),[tee,setTee]=useState('White'),[hole,setHole]=useState('1'),[targets,setTargets]=useState(blankTargets()),[courseMetres,setCourseMetres]=useState(Array(18).fill('')),[gps,setGps]=useState(null),[gpsLive,setGpsLive]=useState(false);"
if old not in s: raise SystemExit('Build 73 state marker missing')
s=s.replace(old,new,1)

s=s.replace('tee:setTee,targets:setTargets,scores:setScores', 'tee:setTee,targets:setTargets,courseMetres:setCourseMetres,scores:setScores', 1)
s=s.replace('course,tee,targets,scores,putts', 'course,tee,targets,courseMetres,scores,putts', 1)
s=s.replace('course,tee,targets,scores,putts,gir,fw,pen,notes,roundLog,practiceHistory,routineSteps,courseInfo,savedCourses})).catch(()=>{})},[units,player,email,handicap,bag,course,tee,targets,scores,putts', 'course,tee,targets,courseMetres,scores,putts,gir,fw,pen,notes,roundLog,practiceHistory,routineSteps,courseInfo,savedCourses})).catch(()=>{})},[units,player,email,handicap,bag,course,tee,targets,courseMetres,scores,putts', 1)
s=s.replace('},[units,player,email,handicap,bag,course,tee,targets,scores,putts', '},[units,player,email,handicap,bag,course,tee,targets,courseMetres,scores,putts', 1)

# Wire the selected tee and course yardage into the round, course importer and scorecard.
s=s.replace("bag={bag} open={open}/>", "bag={bag} tee={tee} open={open}/>", 1)
s=s.replace("savedCourses,setSavedCourses}}/>", "savedCourses,setSavedCourses,courseInfo,setCourseInfo,courseMetres,setCourseMetres}}/>", 1)
s=s.replace("roundLog,setRoundLog,open}}/>", "roundLog,setRoundLog,open,tee,courseMetres,setCourseMetres,handicap}}/>", 1)
s=s.replace("savedCourses,setSavedCourses,courseInfo,setCourseInfo})", "savedCourses,setSavedCourses,courseInfo,setCourseInfo,courseMetres,setCourseMetres})", 1)
s=s.replace("setTargets(Array.isArray(x.targets)&&x.targets.length===18?x.targets:blankTargets());setHole('1')", "setTargets(Array.isArray(x.targets)&&x.targets.length===18?x.targets:blankTargets());setCourseMetres(Array.isArray(x.courseMetres)&&x.courseMetres.length===18?x.courseMetres:Array(18).fill(''));setHole('1')", 1)
s=s.replace("const entry={name,tee,targets};", "const entry={name,tee,targets,courseMetres};", 1)

# Import the selected tee's per-hole distances when the directory provides them.
needle="const preferred=tees.find(x=>String(x?.color||x?.name||'').toLowerCase()===String(tee).toLowerCase())||tees[0],raw=String(preferred?.color||preferred?.name||''),match=TEES.find(x=>x.toLowerCase()===raw.toLowerCase());"
replacement="const preferred=tees.find(x=>String(x?.color||x?.name||'').toLowerCase()===String(tee).toLowerCase())||tees[0],raw=String(preferred?.color||preferred?.name||''),match=TEES.find(x=>x.toLowerCase()===raw.toLowerCase());const teeHoles=preferred?.holes||preferred?.distances||[];if(Array.isArray(teeHoles)&&teeHoles.length)setCourseMetres(Array.from({length:18},(_,i)=>{const z=teeHoles[i]||{};const v=z?.metres??z?.meters??z?.distance_meters??z?.distance_metres??z?.yardage??z?.yards??z;if(v===undefined||v===null||v==='')return'';return String((z?.yardage!==undefined||z?.yards!==undefined)?Math.round(n(v)*.9144):Math.round(n(v))) }));"
if needle not in s: raise SystemExit('Build 73 tee import marker missing')
s=s.replace(needle,replacement,1)

round_new="""function Round({hole,setHole,units,gps,gpsLive,startLiveGPS,stopLiveGPS,targetDistances,wind,windDir,bag,tee,open}){const i=Math.max(0,Math.min(17,n(hole)-1)),arrow=windDir==='HEAD'?'↓':windDir==='TAIL'?'↑':windDir==='L→R'?'→':'←',windType=windDir==='HEAD'?'HEADWIND':windDir==='TAIL'?'TAILWIND':'CROSSWIND',valid=targetDistances.center!==null&&targetDistances.center!==undefined,playing=valid?playsLike(targetDistances.center,wind,0,'Fairway',windDir,units):null,club=valid?nearestClub(playing,bag,units)[0]:'—',step=d=>setHole(String(Math.max(1,Math.min(18,i+1+d))));return <><View style={s.holeStrip}><TouchableOpacity style={s.holeStep} onPress={()=>step(-1)}><Text style={s.holeStepText}>‹</Text></TouchableOpacity><View style={s.center}><Text style={s.holeNumber}>HOLE {i+1}</Text><Text style={s.small}>PAR {PARS[i]} · S.I. {STROKE_INDEX[i]} · {String(tee).toUpperCase()} TEE</Text></View><TouchableOpacity style={s.holeStep} onPress={()=>step(1)}><Text style={s.holeStepText}>›</Text></TouchableOpacity></View><View style={[s.panel,{padding:8}]}><View style={s.mapTop}><Text style={s.panelTitle}>LIVE HOLE VIEW</Text><Text style={[s.gpsStatus,gpsLive&&s.gpsStatusOn]}>{gpsLive?'● GPS ACTIVE':'GPS OFF'}</Text></View><View style={[s.holeMap,{height:390,backgroundColor:'#12382F'}]}><View style={{position:'absolute',top:52,width:120,height:275,backgroundColor:'#4C9461',borderRadius:58,transform:[{rotate:'3deg'}]}}/><View style={{position:'absolute',top:145,left:78,width:58,height:28,borderRadius:20,backgroundColor:'#D8C58E',transform:[{rotate:'-18deg'}]}}/><View style={{position:'absolute',top:235,right:62,width:64,height:30,borderRadius:20,backgroundColor:'#D8C58E',transform:[{rotate:'16deg'}]}}/><View style={[s.mapGreen,{top:18,width:112,height:58}]}/><View style={[s.mapLine,{top:46,height:285}]}/><Text style={[s.mapFlag,{top:35}]}>⚑</Text><View style={[s.mapYou,{bottom:28,width:25,height:25,borderRadius:13}]}/><Text style={[s.mapYouText,{bottom:8}]}>YOU</Text><View style={{position:'absolute',top:82,left:12,backgroundColor:'rgba(4,19,30,.82)',borderRadius:8,padding:7}}><Text style={{color:C.white,fontWeight:'900',fontSize:13}}>{targetDistances.center??'—'} {units==='METRES'?'m':'yd'}</Text><Text style={{color:'#A9D5EE',fontSize:8,fontWeight:'900'}}>TO CENTRE</Text></View><View style={s.mapWind}><Text style={s.mapWindArrow}>{arrow}</Text><Text style={s.mapWindSpeed}>{wind||0} {units==='METRES'?'km/h':'mph'}</Text><Text style={s.mapWindType}>{windType}</Text></View></View></View><View style={s.panel}><View style={s.distanceRow}><Stat a={targetDistances.front??'—'} b="FRONT"/><Stat a={targetDistances.center??'—'} b="CENTRE"/><Stat a={targetDistances.back??'—'} b="BACK"/></View><View style={s.recRow}><View><Text style={s.panelTitle}>CADDIE RECOMMENDATION</Text><Text style={s.bigClub}>{club}</Text></View><Text style={s.playingDistance}>{valid?`PLAYING ${playing} ${units==='METRES'?'m':'yd'}`:'START GPS'}</Text></View></View><Btn text={gpsLive?'STOP LIVE GPS':'START LIVE GPS'} onPress={gpsLive?stopLiveGPS:startLiveGPS}/><View style={{flexDirection:'row',gap:6}}><View style={s.flex}><Btn text="ASK CADDIE" onPress={()=>open('CADDIE')} outline/></View><View style={s.flex}><Btn text="SCORE HOLE" onPress={()=>open('HOLESCORE')} outline/></View></View></>}"""
s,nr=re.subn(r"function Round\(.*?\nfunction Caddie",round_new+'\nfunction Caddie',s,count=1,flags=re.S)
if nr!=1: raise SystemExit('Build 73 round replacement failed')

score_new="""function Score({scores,setScores,putts,setPutts,gir,setGir,fw,setFw,pen,setPen,total,toPar,played,open,tee,courseMetres,setCourseMetres,handicap}){const setA=(setter,a,i,v)=>setter(a.map((x,k)=>k===i?v:x));const[partners]=useState(['Player 2','Player 3','Player 4']);const[ps,setPs]=useState(()=>Array.from({length:3},()=>Array(18).fill('')));useEffect(()=>{AsyncStorage.getItem('CADDIEOS_PARTNER_SCORES_V1').then(v=>{if(v)setPs(JSON.parse(v))}).catch(()=>{})},[]);useEffect(()=>{AsyncStorage.setItem('CADDIEOS_PARTNER_SCORES_V1',JSON.stringify(ps)).catch(()=>{})},[ps]);const setP=(p,i,v)=>setPs(a=>a.map((r,k)=>k===p?r.map((x,j)=>j===i?v:x):r));const nine=(start,label)=>{const ids=Array.from({length:9},(_,j)=>start+j),sum=a=>ids.reduce((q,i)=>q+n(a[i]),0);return <View style={s.scoreCard}><Text style={s.scoreNine}>{label} · {String(tee).toUpperCase()} TEE</Text><View style={s.scoreLine}><Text style={s.scoreLabel}>HOLE</Text>{ids.map(i=><Text key={i} style={s.scoreCellHead}>{i+1}</Text>)}</View><View style={s.scoreLine}><Text style={s.scoreLabel}>METRES</Text>{ids.map(i=><TextInput key={i} style={s.scoreCellPar} value={String(courseMetres[i]||'')} onChangeText={v=>setCourseMetres(courseMetres.map((x,k)=>k===i?v:x))} keyboardType="numeric"/>)}</View><View style={s.scoreLine}><Text style={s.scoreLabel}>PAR</Text>{ids.map(i=><Text key={i} style={s.scoreCellPar}>{PARS[i]}</Text>)}</View><View style={s.scoreLine}><Text style={s.scoreLabel}>S.I.</Text>{ids.map(i=><Text key={i} style={s.scoreCellPar}>{STROKE_INDEX[i]}</Text>)}</View><View style={s.scoreLine}><Text style={s.scoreLabel}>Player 1</Text>{ids.map(i=><TextInput key={i} style={s.scoreCellInput} value={scores[i]} onChangeText={v=>setA(setScores,scores,i,v)} keyboardType="numeric"/>)}</View>{partners.map((p,pi)=><View style={s.scoreLine} key={p}><Text style={s.scoreLabel}>{p}</Text>{ids.map(i=><TextInput key={i} style={s.scoreCellInput} value={ps[pi][i]} onChangeText={v=>setP(pi,i,v)} keyboardType="numeric"/>)}</View>)}<View style={{flexDirection:'row',justifyContent:'space-between',paddingTop:5}}><Text style={s.small}>PAR {ids.reduce((q,i)=>q+PARS[i],0)}</Text><Text style={s.small}>PLAYER 1 {sum(scores)||'—'}</Text></View></View>};return <><Title kicker="ROUND" title="Scorecard" sub={`${played}/18 holes · Handicap ${handicap||'—'} · ${total||0} strokes · ${toPar>=0?'+':''}${toPar}`}/>{nine(0,'FRONT NINE')}{nine(9,'BACK NINE')}<View style={s.panel}><View style={{flexDirection:'row',justifyContent:'space-between'}}><Text style={s.cardTitle}>18-HOLE TOTAL</Text><Text style={s.bigClub}>{total||'—'}</Text></View><Text style={s.small}>TEE: {String(tee).toUpperCase()} · PAR {PARS.reduce((a,b)=>a+b,0)} · NET {total?Math.max(0,total-n(handicap)):'—'}</Text></View><Btn text="ROUND SUMMARY" onPress={()=>open('SUMMARY')}/></>}"""
s,ns=re.subn(r"function Score\(.*?\nfunction Practice",score_new+'\nfunction Practice',s,count=1,flags=re.S)
if ns!=1: raise SystemExit('Build 73 score replacement failed')

app.write_text(s)

g=Path('CaddieOS/android/app/build.gradle')
if g.exists():
    t=g.read_text()
    t=re.sub(r'versionCode\s+\d+','versionCode 73',t,count=1)
    t=re.sub(r'versionName\s+"[^"]+"','versionName "1.0.73"',t,count=1)
    g.write_text(t)
print('Build 73 course view and scorecard applied')
